		t.Fatal("loadSessionState() returned nil")
	}

	if loaded.ShadowBranchSuffix != state.ShadowBranchSuffix {
		t.Errorf("ShadowBranchSuffix = %d, want %d", loaded.ShadowBranchSuffix, state.ShadowBranchSuffix)
	}
}

