    16→// determineSuffix decides which shadow branch suffix to use for the next checkpoint.
    17→//
    18→// Decision logic:
    19→//  1. If no suffix yet (ShadowBranchSuffix == 0), start at suffix 1
    20→//  2. If worktree is clean, previous work was dismissed → new suffix
    21→//  3. If modified files don't overlap with shadow branch files → new suffix
    22→//  4. If modified files overlap but agent's lines are gone → new suffix
    23→//  5. Otherwise, continue on the same suffix (agent's work is preserved)
    24→//
    25→// Returns (suffix, isNew, error) where isNew indicates this is a fresh suffix.
    26→func (s *ManualCommitStrategy) determineSuffix(repo *git.Repository, state *SessionState) (int, bool, error) {
    27→	// Handle legacy sessions (suffix=0)
    28→	if state.ShadowBranchSuffix == 0 {
    29→		return s.handleLegacySuffix(repo, state)
    30→	}
    31→
    32→	// Check if current suffix's branch exists
    33→	currentBranch := checkpoint.ShadowBranchNameForCommitWithSuffix(state.BaseCommit[:checkpoint.ShadowBranchHashLength], state.ShadowBranchSuffix)
    34→	if !shadowBranchExists(repo, currentBranch) {
    35→		// Branch doesn't exist yet, continue with current suffix
    36→		return state.ShadowBranchSuffix, false, nil
    37→	}
    38→
    39→	// Step 1: Clean worktree → new suffix
    40→	clean, err := isWorktreeClean(repo)
    41→	if err != nil {
    42→		return 0, false, fmt.Errorf("failed to check worktree status: %w", err)
    43→	}
    44→	if clean {
    45→		return state.ShadowBranchSuffix + 1, true, nil
    46→	}
    47→
    48→	// Step 2: Get files from shadow branch and worktree
    49→	shadowFiles, err := getFilesFromShadowBranch(repo, state.BaseCommit, currentBranch)
    50→	if err != nil {
    51→		// If we can't read shadow branch, continue with current suffix
    52→		return state.ShadowBranchSuffix, false, nil //nolint:nilerr // Continue on error is by design
    53→	}
    54→
    55→	worktreeFiles, err := getModifiedWorktreeFiles(repo)
    56→	if err != nil {
    57→		// If we can't get worktree files, continue with current suffix
    58→		return state.ShadowBranchSuffix, false, nil //nolint:nilerr // Continue on error is by design
    59→	}
    60→
    61→	// Step 3: Check overlap
    62→	overlap := findFileOverlap(worktreeFiles, shadowFiles)
    63→	if len(overlap) == 0 {
    64→		return state.ShadowBranchSuffix + 1, true, nil
    65→	}
    66→
    67→	// Step 4: Check if agent's lines are preserved in overlapping files
    68→	preserved, err := checkAgentLinesPreserved(repo, state.BaseCommit, currentBranch, overlap)
    69→	if err != nil {
    70→		// If we can't check, err on the side of continuing
    71→		return state.ShadowBranchSuffix, false, nil //nolint:nilerr // Continue on error is by design
    72→	}
    73→	if preserved {
    74→		return state.ShadowBranchSuffix, false, nil
    75→	}
    76→
    77→	// Agent's lines were dismissed
    78→	return state.ShadowBranchSuffix + 1, true, nil
    79→}
