    82→// If a legacy branch exists (entire/<hash>), it renames it to suffixed format (entire/<hash>-1).
    83→func (s *ManualCommitStrategy) handleLegacySuffix(repo *git.Repository, state *SessionState) (int, bool, error) {
    84→	baseCommitShort := state.BaseCommit
