// NewFeatureBranchEnv creates a TestEnv ready for session testing.
// It initializes the repo, creates an initial commit on main,
// and checks out a feature branch. This is the most common setup
// for session and rewind tests since Entire tracking skips main/master.
func NewFeatureBranchEnv(t *testing.T, strategyName string) *TestEnv {
	t.Helper()
	env := NewRepoWithCommit(t, strategyName)
	env.GitCheckoutNewBranch("feature/test-branch")
	return env
}

// NewFeatureBranchEnvWithOptions creates a TestEnv ready for session testing with custom options.
// Similar to NewFeatureBranchEnv but allows specifying strategy options like enable_multisession_warning.
func NewFeatureBranchEnvWithOptions(t *testing.T, strategyName string, strategyOptions map[string]any) *TestEnv {
	t.Helper()
	env := NewTestEnv(t)
	env.InitRepo()
	env.InitEntireWithOptions(strategyName, strategyOptions)
	env.WriteFile("README.md", "# Test Repository")
	env.GitAdd("README.md")
	env.GitCommit("Initial commit")
	env.GitCheckoutNewBranch("feature/test-branch")
	return env
}

